def gcd(*numbers):
    """Calculate the Greatest Common Divisor of the numbers."""
    if len(numbers) == 2:
        a, b = numbers
        while b:
            a, b = b, a % b
        return a
    elif len(numbers) < 2:
        raise TypeError(
            'gcd expected at least 2 arguments, got ' + str(len(numbers)))
    else:
        val = numbers[0]
        for i in numbers[1:]:
            while i:
                val, i = i, val % i
        return val

