def is_perm_palindrome(s):
    """
    Returns a boolean which is True if the string
    is a permutation of a palindrome

    >>> is_perm_palindrome('Tact Coa')
    True`
    Taco Cat

    >>> is_perm_palindrome('ab')
    False
    """
    matches = {}

    for c in s:
        if c != ' ':
            l = c.lower()
            if l in matches:
                matches[l] = not matches[l]
            else:
                matches[l] = False

