  """
  Bellman-Ford finds the shortest path to
  each vertex from s in a graph
  which may have negative cycles

  If it detects a negative cycle, it
  will raise an Exception

  Complexity: O(v * e)

  """
  predecessors = {}
  path_costs = {}
  for v in adjaceny_list:
    predecessors[v] = None
    path_costs[v] = float('inf')
