      if path_costs[u] + weights[edge] < path_costs[v]:
        path_costs[v] = path_costs[u] + weights[edge]
        predecessors[v] = u
  for edge in weights:
    u, v = edge
    if path_costs[u] + weights[edge] < path_costs[v]:
